Alright, I've ironed out the last remaining issues and the backup block is working. I've been backing up Vaultwarden using Restic to a local directory (on another HDD) and to Backblaze thanks to the following config.

You'll notice I don't need to tell which directory to save nor which user to use thanks to the backup contract. The contract is essentially the snippet `config.shb.vaultwarden.backup //`.

```nix
shb.restic.instances."vaultwarden" = config.shb.vaultwarden.backup // {
  enable = true;

  passphraseFile = config.sops.secrets."vaultwarden/backup/passphrase".path;

  repositories = [
    {
      path = "/srv/backup/restic";
      timerConfig = {
        OnCalendar = "00:00:00";
        RandomizedDelaySec = "3h";
      };
    }
    {
      path = "s3:s3.us-west-000.backblazeb2.com/<mybucket>";
      timerConfig = {
        OnBootSec = "15min";
        OnUnitActiveSec = "1h";
        RandomizedDelaySec = "7min";
      };
      secrets = {
        AWS_ACCESS_KEY_ID.source = config.sops.secrets."backup/b2/access_key_id".path;
        AWS_SECRET_ACCESS_KEY.source = config.sops.secrets."backup/b2/secret_access_key".path;
      };
    }
  ];

  retention = {
    keep_within = "1d";
    keep_hourly = 24;
    keep_daily = 7;
    keep_weekly = 4;
    keep_monthly = 6;
  };
};

sops.secrets."vaultwarden/backup/passphrase" = {
  sopsFile = ./secrets.yaml;
  mode = "0400";
  owner = "vaultwarden";
  group = "vaultwarden";
};
sops.secrets."backup/b2/access_key_id" = {
  sopsFile = ./secrets.yaml;
  mode = "0400";
  owner = "vaultwarden";
  group = "vaultwarden";
};
sops.secrets."backup/b2/secret_access_key" = {
  sopsFile = ./secrets.yaml;
  mode = "0400";
  owner = "vaultwarden";
  group = "vaultwarden";
};
```

